// ============================================================
// KONFIGURASI UTAMA — UBAH DI SINI
// ============================================================
// Untuk mengganti provider LLM, ubah nilai di bawah:
//
// PROVIDER OPTIONS:
//   'googleGemini'   → Google Gemini (default)
//   'openAi'         → OpenAI GPT
//   'anthropic'      → Anthropic Claude
//   'ollama'         → Ollama (local)
//
// Credential name harus sesuai dengan nama credential
// yang sudah kamu buat di n8n Settings > Credentials.
// ============================================================

const CONFIG = {
  // --- PROVIDER AKTIF ---
  // Ganti nilai ini untuk switch provider semua agent sekaligus
  activeProvider: 'googleGemini',

  // --- MODEL PER PROVIDER ---
  models: {
    googleGemini: 'models/gemini-2.0-flash',
    openAi: 'gpt-4o',
    anthropic: 'claude-sonnet-4-5',
    ollama: 'llama3.1'
  },

  // --- NAMA CREDENTIAL DI N8N ---
  // Pastikan nama ini sama persis dengan credential di n8n
  credentials: {
    googleGemini: 'Google Gemini API',
    openAi: 'OpenAI API',
    anthropic: 'Anthropic API',
    ollama: 'Ollama API'
  },

  // --- GITHUB (aktifkan jika perlu commit otomatis) ---
  github: {
    enabled: false,           // Ubah ke true untuk aktifkan GitHub commit
    credentialName: 'GitHub API',
    owner: 'dikkycenter',
    repo: 'spp-sekolah',
    branch: 'main'
  }
};

// Ambil input dari webhook
const body = $input.first().json.body || $input.first().json;
const userRequest = body.request || body.message || body.task || '';
const targetAgent = body.agent || 'project_manager'; // bisa override agent tertentu

if (!userRequest) {
  throw new Error('Request kosong. Kirim JSON dengan field "request" berisi deskripsi tugas.');
}

return [{
  json: {
    config: CONFIG,
    userRequest: userRequest,
    targetAgent: targetAgent,
    timestamp: new Date().toISOString(),
    activeModel: CONFIG.models[CONFIG.activeProvider],
    activeProvider: CONFIG.activeProvider
  }
}];

