// Parse response dari Project Manager
const response = $input.first().json;
const prevData = $('Config & Init').first().json;

let pmOutput;
try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
  // Bersihkan markdown code block jika ada
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  pmOutput = JSON.parse(cleaned);
} catch(e) {
  pmOutput = {
    task_id: 'PM-ERR-001',
    summary: 'Gagal parse output PM',
    tasks: [],
    raw: response.candidates?.[0]?.content?.parts?.[0]?.text || 'No response',
    error: e.message
  };
}

return [{
  json: {
    ...prevData,
    pm_output: pmOutput,
    current_step: 'project_manager_done'
  }
}];

const response = $input.first().json;
const prevData = $('Parse PM Output').first().json;

