try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  dbOutput = JSON.parse(cleaned);
} catch(e) {
  dbOutput = {
    files: [],
    raw: response.candidates?.[0]?.content?.parts?.[0]?.text || 'No response',
