// ============================================================
// GITHUB COMMIT NODE
// Aktifkan dengan mengubah config.github.enabled = true
// di node 'Config & Init'
// ============================================================
//
// SETUP GITHUB:
// 1. Buat Personal Access Token di GitHub:
//    Settings → Developer Settings → Personal Access Tokens → Fine-grained tokens
//    Permissions: Contents (read & write), Metadata (read)
// 2. Di n8n: Settings → Credentials → Add Credential → GitHub API
//    Masukkan token tersebut
// 3. Ubah config.github.enabled = true di node 'Config & Init'
// 4. Sesuaikan config.github.owner dan config.github.repo
//
// CATATAN: Node ini sudah siap pakai, tidak perlu modifikasi lain.
// ============================================================

const data = $input.first().json;
const githubConfig = data.config.github;

if (!githubConfig.enabled) {
  return [{
    json: {
      ...data,
      github_output: {
        status: 'SKIPPED',
        message: 'GitHub commit dinonaktifkan. Set config.github.enabled = true untuk mengaktifkan.',
        commit_message: data.tw_output?.commit_message || ''
      },
      current_step: 'github_skipped'
    }
  }];
}

// Jika enabled, data akan diteruskan ke HTTP Request node GitHub
return [{
  json: {
    ...data,
    github_ready: true,
    current_step: 'github_preparing'
  }
}];

// ============================================================
// GITHUB COMMIT EXECUTOR
// Node ini hanya berjalan jika github_ready = true
// Untuk menggunakan, pastikan sudah setup credential GitHub di n8n
// ============================================================

const data = $input.first().json;

if (!data.github_ready) {
  return [$input.first()];
}

// Kumpulkan semua file yang dihasilkan
const allFiles = [
  ...(data.db_output?.files || []),
  ...(data.backend_output?.files || []),
  ...(data.frontend_output?.files || [])
];

// Persiapkan data untuk GitHub API
const githubPayload = {
  owner: data.config.github.owner,
  repo: data.config.github.repo,
  branch: data.config.github.branch,
  commit_message: data.tw_output?.commit_message || 'chore: update via n8n workflow',
  files: allFiles.map(f => ({
    path: (f.path + f.filename).replace(/\/\//g, '/'),
    content: f.content
  }))
};

return [{
  json: {
    ...data,
    github_payload: githubPayload,
    github_output: {
      status: 'PENDING',
      message: `Siap commit ${allFiles.length} file ke ${data.config.github.owner}/${data.config.github.repo}`,
      files_count: allFiles.length
    },
    current_step: 'github_commit_prepared'
  }
}];

// ============================================================
// UNTUK IMPLEMENTASI PENUH GITHUB COMMIT:
// Tambahkan HTTP Request node setelah ini dengan:
// URL: https://api.github.com/repos/{{owner}}/{{repo}}/git/refs/heads/{{branch}}
// Method: GET
// Auth: GitHub credential
// Kemudian gunakan SHA-nya untuk membuat tree dan commit
// Referensi: https://docs.github.com/en/rest/git
// ============================================================

// Kompilasi hasil final dari seluruh pipeline
const data = $input.first().json;

// Kumpulkan semua file
const allFiles = [
  ...(data.db_output?.files || []).map(f => ({...f, agent: 'Database Designer'})),
  ...(data.backend_output?.files || []).map(f => ({...f, agent: 'Backend Developer'})),
  ...(data.frontend_output?.files || []).map(f => ({...f, agent: 'Frontend Developer'}))
];

const summary = {
  status: 'SUCCESS',
  workflow: 'Sistem SPP Sekolah - AI Agent Pipeline',
  timestamp: new Date().toISOString(),
  user_request: data.userRequest,
  provider_used: data.activeProvider,
  model_used: data.activeModel,

  pipeline_summary: {
    project_manager: {
      task_id: data.pm_output?.task_id,
      summary: data.pm_output?.summary,
      total_tasks: data.pm_output?.tasks?.length || 0
    },
    database_designer: {
      files_generated: data.db_output?.files?.length || 0,
      filenames: data.db_output?.files?.map(f => f.filename) || []
    },
    backend_developer: {
      files_generated: data.backend_output?.files?.length || 0,
      filenames: data.backend_output?.files?.map(f => f.filename) || []
    },
    frontend_developer: {
      files_generated: data.frontend_output?.files?.length || 0,
      filenames: data.frontend_output?.files?.map(f => f.filename) || []
    },
    qa_reviewer: {
      verdict: data.qa_output?.verdict,
      issues_count: data.qa_output?.issues?.length || 0,
      critical_issues: data.qa_output?.issues?.filter(i => i.severity === 'critical') || [],
      checklist: data.qa_output?.checklist
    },
    technical_writer: {
      commit_message: data.tw_output?.commit_message
    },
    github: {
      status: data.github_output?.status,
      message: data.github_output?.message
    }
  },

  total_files_generated: allFiles.length,
  files: allFiles,

  definition_of_done: {
    migrations_ready: (data.db_output?.files?.length || 0) > 0,
    no_syntax_errors: data.qa_output?.checklist?.syntax || false,
    qa_approved: data.qa_output?.verdict === 'APPROVED',
    fifo_logic_verified: data.qa_output?.checklist?.logic_fifo || false,
    no_duplicate_billing: data.qa_output?.checklist?.logic_no_duplicate || false,
    scope_compliance: data.qa_output?.checklist?.scope_compliance || false
  }
};

return [{ json: summary }];

// Output ketika QA TIDAK APPROVED — kirim laporan revision
const data = $input.first().json;

const revisionReport = {
  status: 'REVISION_NEEDED',
  workflow: 'Sistem SPP Sekolah - AI Agent Pipeline',
  timestamp: new Date().toISOString(),
  user_request: data.userRequest,

  qa_result: {
    verdict: data.qa_output?.verdict,
    summary: data.qa_output?.summary,
    critical_issues: data.qa_output?.issues?.filter(i => i.severity === 'critical') || [],
    warnings: data.qa_output?.issues?.filter(i => i.severity === 'warning') || [],
    suggestions: data.qa_output?.issues?.filter(i => i.severity === 'suggestion') || [],
    checklist: data.qa_output?.checklist
  },

  message: 'QA tidak memberikan APPROVED. Silakan review issues di atas dan jalankan ulang workflow setelah diperbaiki.',
  next_steps: [
    'Review critical issues terlebih dahulu',
    'Perbaiki masalah yang ditemukan QA',
    'Jalankan ulang workflow dengan request yang sama'
  ]
};

return [{ json: revisionReport }];
